      SUBROUTINE THRED3(UA,COR)CC     THIRD-ORDER TRANSFORMATION OF BEAM CENTROIDC ----------------------------------------------------------------------C     LOCAL VARIABLESC      REAL       COR(6), COT(6), UA(5,56)C ----------------------------------------------------------------------CC     THIRD-ORDER TERMSC      DO 20 J = 1, 5      SS = 0.0      IND = 0      DO 10 L3 = 1, 6      DO 10 L2 = 1, L3      DO 10 L1 = 1, L2      IND = IND + 1      SS = SS + UA(J,IND)*COR(L1)*COR(L2)*COR(L3)   10 CONTINUE      COT(J) =  SS   20 CONTINUE      COT(6) = 0.0CC     RESET OFF-AXIS REFERENCE TRAJECTORYC      DO 50 J = 1, 6   50 COR(J) = COT(J)      RETURN      END